package main

import (
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"loft.local/wickpane/pantryc"
	"loft.local/wickpane/spoolkit"
)

func stageFile(path string, data []byte) (string, error) {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return "", err
	}
	f, err := os.CreateTemp(dir, "."+filepath.Base(path)+"-*")
	if err != nil {
		return "", err
	}
	name := f.Name()
	ok := false
	defer func() {
		if !ok {
			_ = os.Remove(name)
		}
	}()
	if err = f.Chmod(0o644); err == nil {
		_, err = f.Write(data)
	}
	if err == nil {
		err = f.Sync()
	}
	if closeErr := f.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return "", err
	}
	ok = true
	return name, nil
}

func runBin() int {
	const dir = "/app/shardops/live"
	const outPath = "/app/shardops/bins.json"
	const shaPath = "/app/loomwell/pair.sha"

	entries, err := os.ReadDir(dir)
	if err != nil {
		return 1
	}
	out := make(map[string]string)
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".stk") {
			continue
		}
		rows, err := spoolkit.Scan(filepath.Join(dir, e.Name()))
		if err != nil {
			// In particular, a BAD take aborts before either output is staged.
			return 1
		}
		stem := strings.TrimSuffix(e.Name(), ".stk")
		out[stem] = pantryc.Join(pipeBack(pipeFront(rows)))
	}

	n7, nOK := out["n7"]
	s7, sOK := out["s7"]
	if !nOK || !sOK || n7 != s7 {
		return 1
	}
	sum := sha256.Sum256([]byte(n7))
	shaBlob := []byte(fmt.Sprintf("%x\n", sum))
	jsonBlob, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return 1
	}
	jsonBlob = append(jsonBlob, '\n')

	jsonTmp, err := stageFile(outPath, jsonBlob)
	if err != nil {
		return 1
	}
	defer os.Remove(jsonTmp)
	shaTmp, err := stageFile(shaPath, shaBlob)
	if err != nil {
		return 1
	}
	defer os.Remove(shaTmp)

	if err := os.Rename(shaTmp, shaPath); err != nil {
		return 1
	}
	if err := os.Rename(jsonTmp, outPath); err != nil {
		return 1
	}
	return 0
}
